package io.github.mbaliga.clavis.ui.colophon

/** One entry of the colophon's `References` card: `[id] {s}. {t} — {n}` (template L613–654). */
data class Ref(val id: Int, val s: String, val t: String, val u: String, val n: String)

/**
 * The 40 references, verbatim from the v0.10 web build (`REFS`, template-spec §7.10). Ids are
 * stable forever (R-8): new references are appended as 41+, never renumbered.
 */
val REFERENCES: List<Ref> = listOf(
    Ref(1, "Nation 2006", "How large a vocabulary is needed for reading and listening?", "https://www.scienceguide.nl/wp-content/uploads/2017/11/nation-2006-vocabulary.pdf", "2,000 word families cover ~89% of conversation; 98% coverage needs 6,000–9,000."),
    Ref(2, "Cepeda et al. 2008", "Spacing effects in learning: a temporal ridgeline of optimal retention", "https://files.eric.ed.gov/fulltext/ED505660.pdf", "1,354 people; recall 64% higher at the optimal gap; the gap grows with how long you want to remember."),
    Ref(3, "Karpicke & Roediger 2008", "The critical importance of retrieval for learning", "https://web.mit.edu/jbelcher/www/learner/retrieval.pdf", "Tested learners recalled ~80% a week later; re-studiers 33–36%."),
    Ref(4, "Webb 2007", "The effects of repetition on vocabulary knowledge", "https://academic.oup.com/applij/article-abstract/28/1/46/174744", "~10 encounters is the working dose for incidental word learning."),
    Ref(5, "Schmidt 1990", "The role of consciousness in second language learning", "https://academic.oup.com/applij/article-abstract/11/2/129/163482", "\"Subliminal language learning is impossible\" — attention is required; Clavis never claims sleep-learning."),
    Ref(6, "Gooskens et al. 2017", "Mutual intelligibility between closely related languages in Europe", "https://www.let.rug.nl/gooskens/pdf/publ_ijm_2017.pdf", "Untrained listeners: Portuguese→Spanish 77%, Spanish→Portuguese 37%; reception is cheap, and asymmetric."),
    Ref(7, "Lotto & de Groot 1998", "Effects of learning method and word type on acquiring vocabulary", "https://www.academia.edu/12744827/", "Cognates recalled 86.5% vs 72% for non-cognates."),
    Ref(8, "Rothman 2011", "The Typological Primacy Model", "https://journals.sagepub.com/doi/10.1177/0267658310386439", "Transfer comes from the language you perceive as closest, not your first."),
    Ref(9, "Carvalho & da Silva 2006", "Cross-linguistic influence in third language acquisition", "https://eric.ed.gov/?id=EJ741850", "Producing two sibling languages early breeds blends (portuñol); Clavis widens reading, narrows speaking."),
    Ref(10, "Clement, Roy, Oudeyer & Lopes 2015", "Multi-armed bandits for intelligent tutoring systems", "https://arxiv.org/abs/1310.3174", "ZPDES: pick the next activity by learning progress, per learner, no population data — the engine behind Paths."),
    Ref(11, "Doignon & Falmagne 1985–2012", "Knowledge space theory", "https://link.springer.com/book/10.1007/978-3-642-58625-5", "What you know is a state in a prerequisite structure; the \"fringe\" is what you are ready to learn next."),
    Ref(12, "Open Spaced Repetition 2023–26", "FSRS benchmark (~350M reviews)", "https://github.com/open-spaced-repetition/srs-benchmark", "FSRS beats SM-2 in ~99.6% of collections; Clavis schedules every word with FSRS-5."),
    Ref(13, "Nakata & Suzuki 2019", "Mixing semantically related words hurts", "https://www.cambridge.org/core/journals/studies-in-second-language-acquisition/article/effects-of-massing-and-spacing-on-the-learning-of-semantically-related-and-unrelated-words/F58BA8D70385603B9C42E408BFCB8A10", "Days-of-the-week-style sets interfere ~3× more; Clavis never introduces them together."),
    Ref(14, "Yonelinas 2002", "The nature of recollection and familiarity", "https://doi.org/10.1006/jmla.2002.2864", "Familiarity without recollection is real memory signal — the \"tingle.\""),
    Ref(15, "Nelson 1978", "Savings in relearning", "https://psycnet.apa.org/doi/10.1037/0278-7393.4.5.453", "Words you can neither recall nor recognise are still relearned faster than new ones."),
    Ref(16, "Bowers, Mattys & Gage 2009", "Preserved implicit knowledge of a forgotten childhood language", "https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02407.x", "Adults relearned \"lost\" Hindi/Zulu phonemes better than controls, with no explicit memory."),
    Ref(17, "Frances, Martín & Duñabeitia 2020", "The effects of contextual diversity on word learning", "https://www.nature.com/articles/s41598-020-70922-1", "Same 8 exposures across more texts → better recall, recognition and meaning — including in a foreign language."),
    Ref(18, "Rosa, Tapia & Perea 2017", "Contextual diversity in children's word learning", "https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0179004", "Words met across genres beat words met in one, on every measure."),
    Ref(19, "Adelman, Brown & Quesada 2006", "Contextual diversity, not word frequency, determines word-naming and lexical decision times", "https://journals.sagepub.com/doi/10.1111/j.1467-9280.2006.01787.x", "The count that matters is distinct contexts, not raw repetitions."),
    Ref(20, "Ludke, Ferreira & Overy 2014", "Singing can facilitate foreign language learning", "https://link.springer.com/article/10.3758/s13421-013-0342-5", "Singing beat speaking for verbatim phrase production (d ≈ 0.75)."),
