    Ref(23, "Souza & Barbosa 2023", "Should we turn off the music?", "https://journalofcognition.org/articles/10.5334/joc.273", "Background music with lyrics impairs verbal memory and reading (d ≈ −0.3); Clavis plays nothing behind exercises."),
    Ref(24, "Sundararajan & Adesope 2020", "Keep it coherent: seductive details meta-analysis", "https://link.springer.com/article/10.1007/s10648-020-09522-4", "Interesting-but-irrelevant media reliably hurts learning; every picture here depicts the phrase."),
    Ref(25, "Barcroft 2002", "Semantic and structural elaboration in L2 lexical acquisition", "https://eric.ed.gov/?id=EJ647300", "Deep meaning-work at first exposure suppresses learning the word form — so origins unlock on the second meeting."),
