    Ref(28, "Deci, Koestner & Ryan 1999", "Meta-analysis of extrinsic rewards and intrinsic motivation", "https://psycnet.apa.org/doi/10.1037/0033-2909.125.6.627", "Expected tangible rewards undermine intrinsic motivation; informational feedback strengthens it. No XP here."),
    Ref(29, "Lally et al. 2010", "How are habits formed", "https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674", "Median 66 days to automaticity; missing one day doesn't dent the curve — streak guilt is not evidence-based."),
    Ref(30, "Kang, McDermott & Roediger 2007", "Test format and corrective feedback", "https://doi.org/10.1080/09541440601056620", "Short-answer practice beats multiple choice for later retention — recall before recognition."),
    Ref(31, "Sarma 2025", "Heritage, multilingualism and education in India (IIT Bombay, n = 1,375)", "https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2025.1538482/full", "English-medium graduates keep spoken heritage languages but cede reading and formal register — why the baseline tests exist."),
    Ref(32, "Fourrier & Sagot 2020", "EtymDB 2.0: a large etymological database from Wiktionary", "https://aclanthology.org/2020.lrec-1.397/", "Source of the real inheritance/borrowing/cognacy links in the Cosmos (CC BY-SA 4.0)."),
    Ref(33, "Skirgård, Roberts & Yencken 2017", "Why are some languages confused for others? Investigating data from the Great Language Game", "https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0165934", "Nearly 15 million guesses across 78 languages: a language is confused with its geographic neighbours more often than with its genealogical relatives."),
    Ref(34, "Girgin 2017", "Cues used by teacher candidates to locate places in GeoGuessr", "https://files.eric.ed.gov/fulltext/ED581261.pdf", "Among 103 participants, written signs were the single largest cue category (~30%) for placing an unfamiliar scene — script is a geographic signal."),
    Ref(35, "Brady, Konkle, Alvarez & Oliva 2008", "Visual long-term memory has a massive storage capacity for object details", "https://www.pnas.org/doi/abs/10.1073/pnas.0803390105", "After seeing 2,500 objects once, people recognised them at 87–92% — a glimpse leaves far more trace than it feels like."),
    Ref(36, "Furnas 1986", "Generalized fisheye views", "https://dl.acm.org/doi/10.1145/22627.22342", "Degree-of-interest views: magnify what is in focus while keeping the surroundings in sight — the idea behind the Cosmos fisheye."),
    Ref(37, "Sarkar & Brown 1992", "Graphical fisheye views of graphs", "https://dl.acm.org/doi/10.1145/142750.142763", "The distortion behind the Explore fisheye: points near the lens centre spread apart, distant ones compress — and the space gained is spent on labels. Full report: bitsavers.org/pdf/dec/tech_reports/SRC-RR-84A.pdf"),
    Ref(38, "Tominski, Gladisch, Kister, Dachselt & Schumann 2017", "Interactive lenses for visualization: an extended survey", "https://onlinelibrary.wiley.com/doi/10.1111/cgf.12871", "Survey of lens techniques including the local edge filters the Relations lens implements."),
    Ref(39, "Collins, Penn & Carpendale 2009", "Bubble Sets: revealing set relations with isocontours over existing visualizations", "https://ieeexplore.ieee.org/document/5290706/", "Set membership drawn as smooth isocontours over a point cloud — the Families outline and the Paths groupings, drawn by the BubbleSets algorithm itself (via AntV G6)."),
    Ref(40, "Fruchterman & Reingold 1991", "Graph drawing by force-directed placement", "https://onlinelibrary.wiley.com/doi/10.1002/spe.4380211102", "Springs pull related nodes together, repulsion pushes all apart — the layout used for a word's web, and (as d3-force) for the Paths map."),
